            @p_d2 bra SKIP_K2_OP;
                add.u64 addr2, addr, off2;
                ld.global.b16 hbits, [addr2];
                mov.b16 htmp, hbits;
                cvt.f32.f16 kval, htmp;
                fma.rn.f32 part, q2, kval, part;
        SKIP_K2_OP:
            @p_d3 bra SKIP_K3_OP;
                add.u64 addr2, addr, off3;
                ld.global.b16 hbits, [addr2];
