            add.u64 addr2, sbase, addr2;
            st.shared.f32 [addr2], part;
    SKIP_WARP_STORE_OP:
        bar.sync 0;
        // cross-warp reduction by warp 0
        setp.ne.u32 p0, wid, 0;
