# Ensure PTX is pure ASCII (ptxas requires 7-bit ASCII)
def _sanitize_ptx_ascii(s: str) -> str:
    repl = {
        '\u00b7': '*',   # middle dot
        '\u2013': '-',   # en dash
        '\u2014': '-',   # em dash
        '\u2212': '-',   # unicode minus
        '\u00a0': ' ',   # non-breaking space
    }
    return ''.join(repl.get(ch, ch) for ch in s)
PTX_SOURCE = _sanitize_ptx_ascii(PTX_SOURCE)
_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    _get_ptx_module().function("sdp_attn_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        assert Q.is_cuda and K.is_cuda and V.is_cuda
        assert Q.dtype == torch.float16 and K.dtype == torch.float16 and V.dtype == torch.float16
        B, H, S, D = Q.shape
        out = torch.empty_like(Q)
        module = _get_ptx_module()
        module.launch(
            "sdp_attn_kernel",
            grid=(S, H, B),
            block=(256, 1, 1),
            arguments=[Q, K, V, out, i32(B), i32(H), i32(S), i32(D)],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return out

